'use strict';
const $=id=>document.getElementById(id);let rows=[],result=null;const names=['林小安','陳以晴','王子涵','張家睿','李佳穎','黃柏宇','吳欣怡','周品妤'];
const now=new Date(),next=new Date(now.getFullYear(),now.getMonth()+1,1);$('month').value=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}`;
function notice(message){const el=$('toast');el.textContent=message;el.style.display='block';clearTimeout(notice.t);notice.t=setTimeout(()=>el.style.display='none',4000)}
function days(){const [y,m]=$('month').value.split('-').map(Number);return new Date(y,m,0).getDate()}
function dateOf(day){return `${$('month').value}-${String(day).padStart(2,'0')}`}
function demo(){let list=names.map(姓名=>({姓名,日期:'',需求:''}));names.forEach((姓名,i)=>{[3+i*2,15+i].forEach(n=>list.push({姓名,日期:dateOf(n),需求:'休假'}));list.push({姓名,日期:dateOf(25+i%4),需求:i%2?'晚班':'早班'})});return list}
function saveWorkbook(sheetRows,filename,sheetName){const w=XLSX.utils.book_new(),s=XLSX.utils.aoa_to_sheet(sheetRows);s['!cols']=sheetRows[0].map((_,i)=>({wch:i===0?17:13}));XLSX.utils.book_append_sheet(w,s,sheetName);XLSX.writeFile(w,filename)}
function template(){const d=demo();saveWorkbook([['姓名','日期','需求'],...d.map(r=>[r.姓名,r.日期,r.需求])],`排班需求範例_${$('month').value}.xlsx`,'排班需求');notice('範例需求表已下載')}
$('downloadTemplate').onclick=template;$('templateInline').onclick=template;
$('sample').onclick=()=>{rows=demo();$('fileStatus').textContent=`已載入模擬資料：${names.length} 位同仁，${$('month').value} 的需求`;$('result').hidden=true;notice('已載入模擬資料，現在可以產生班表')};
function normDate(v){if(!v)return '';if(v instanceof Date)return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);return d?`${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`:''}const s=String(v).trim().replace(/[年月/.]/g,'-').replace(/日/g,'');const match=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);if(!match)return 'invalid';let y=+match[1],m=+match[2],d=+match[3],dt=new Date(y,m-1,d);return dt.getFullYear()===y&&dt.getMonth()===m-1&&dt.getDate()===d?`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`:'invalid'}
async function loadFile(file){if(!file)return;try{const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});const data=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});if(!data.length||!['姓名','日期','需求'].every(k=>k in data[0]))throw Error('找不到「姓名、日期、需求」欄位，請使用範例格式。');let arr=data.map(r=>({姓名:String(r.姓名).trim(),日期:normDate(r.日期),需求:String(r.需求).trim()})).filter(r=>r.姓名);if(!arr.length)throw Error('需求表中沒有同仁姓名。');for(const r of arr){if(r.日期==='invalid')throw Error(`${r.姓名} 的日期無法辨識，請使用 YYYY-MM-DD 格式。`);if(r.需求&&!['休假','早班','晚班'].includes(r.需求))throw Error(`${r.姓名} 的需求「${r.需求}」無法辨識，請填休假、早班或晚班。`);if(!!r.日期!==!!r.需求)throw Error(`${r.姓名} 的日期與需求必須同時填寫，或兩者留白。`)}const seen=new Set();for(const r of arr.filter(x=>x.日期)){let key=r.姓名+'|'+r.日期;if(seen.has(key))throw Error(`${r.姓名} 在 ${r.日期} 有重複需求，請先整理。`);seen.add(key)}rows=arr;$('fileStatus').textContent=`已載入：${file.name} · ${new Set(rows.map(r=>r.姓名)).size} 位同仁`;$('result').hidden=true;notice('需求表已載入')}catch(e){rows=[];$('fileStatus').textContent='檔案載入失敗';notice(e.message||'無法讀取檔案，請確認檔案格式。')}}
$('file').onchange=e=>loadFile(e.target.files[0]);const drop=$('drop');['dragenter','dragover'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>loadFile(e.dataTransfer.files[0]));
$('generate').onclick=()=>{if(!rows.length)return notice('請先上傳需求表或使用模擬資料');if(!$('month').value)return notice('請選擇排班月份');const early=Number($('early').value),late=Number($('late').value),max=Number($('maxDays').value);if(!Number.isInteger(early)||!Number.isInteger(late)||early<0||late<0||early>30||late>30||!Number.isInteger(max)||max<1||max>31)return notice('請輸入有效的班別人數及連續上班天數');let staff=[...new Set(rows.map(r=>r.姓名))],prefs=new Map(),different=0;for(const r of rows){if(r.日期&&!r.日期.startsWith($('month').value+'-'))different++;else if(r.日期)prefs.set(r.姓名+'|'+r.日期,r.需求)}if(different)notice(`有 ${different} 筆需求不在所選月份，未納入排班`);let state=staff.map((name,i)=>({name,i,streak:0,count:0,early:0,late:0,shifts:[]})),short=[],unmet=[];for(let day=1;day<=days();day++){let date=dateOf(day),used=new Set();for(const [shift,need] of [['早班',early],['晚班',late]]){for(let n=0;n<need;n++){let pool=state.filter(s=>!used.has(s.name)&&prefs.get(s.name+'|'+date)!=='休假'&&s.streak<max);pool.sort((a,b)=>{const score=s=>s.count*10+(shift==='早班'?s.early:s.late)*2-(prefs.get(s.name+'|'+date)===shift?7:0)+(prefs.get(s.name+'|'+date)&&prefs.get(s.name+'|'+date)!==shift?7:0);return score(a)-score(b)||((a.i-day+staff.length*40)%staff.length)-((b.i-day+staff.length*40)%staff.length)});if(!pool.length){short.push(`${date.slice(5)} ${shift}`);continue}let s=pool[0];used.add(s.name);s.shifts.push(shift);s.count++;if(shift==='早班')s.early++;else s.late++}}for(const s of state){if(used.has(s.name))s.streak++;else{s.shifts.push('休');s.streak=0}const pref=prefs.get(s.name+'|'+date);if(pref&&pref!=='休假'&&s.shifts[day-1]!==pref)unmet.push(`${date.slice(5)} ${s.name}（希望${pref}）`)}}
result={state,short,unmet,month:$('month').value,early,late,max,different};render();$('result').hidden=false;$('result').scrollIntoView({behavior:'smooth'});};
function render(){let r=result;$('summary').textContent=`${r.month} · ${r.state.length} 位同仁 · 早班 ${r.early} 人 / 晚班 ${r.late} 人`;let alerts=$('alerts');alerts.replaceChildren();function add(text,success=false){let p=document.createElement('div');p.className='alert'+(success?' success':'');p.textContent=text;alerts.append(p)}if(!r.short.length&&!r.unmet.length&&!r.different)add('✓ 已排滿每日班別，並符合本月所有班別偏好。',true);if(r.short.length)add(`未排滿 ${r.short.length} 個班次：${r.short.slice(0,12).join('、')}${r.short.length>12?' 等，請調整人數或規則後重新產生；目前結果不代表一定無解。':'。請調整人數或規則後重新產生；目前結果不代表一定無解。'}`);if(r.unmet.length)add(`未滿足 ${r.unmet.length} 筆班別偏好：${r.unmet.slice(0,8).join('、')}${r.unmet.length>8?' 等。':'。'}`);if(r.different)add(`${r.different} 筆需求不在所選月份，未納入排班。`);let table=$('schedule');table.replaceChildren();let tr=document.createElement('tr');for(const x of ['同仁',...Array.from({length:days()},(_,i)=>String(i+1)), '早班','晚班','總班數']){let th=document.createElement('th');th.textContent=x;tr.append(th)}table.append(tr);for(const s of r.state){let row=document.createElement('tr');for(const [i,val] of [s.name,...s.shifts,s.early,s.late,s.count].entries()){let td=document.createElement('td');td.textContent=val;if(i>0&&i<=s.shifts.length)td.className=val==='早班'?'early':val==='晚班'?'late':'off';row.append(td)}table.append(row)}}
$('export').onclick=()=>{if(!result)return;const r=result;const header=['同仁',...Array.from({length:r.state[0].shifts.length},(_,i)=>`${r.month}-${String(i+1).padStart(2,'0')}`),'早班數','晚班數','總班數'];const w=XLSX.utils.book_new();XLSX.utils.book_append_sheet(w,XLSX.utils.aoa_to_sheet([header,...r.state.map(s=>[s.name,...s.shifts,s.early,s.late,s.count])]),'班表');XLSX.utils.book_append_sheet(w,XLSX.utils.aoa_to_sheet([['排班說明'],['排班月份',r.month],['每日早班人數',r.early],['每日晚班人數',r.late],['最多連續上班天數',r.max],['未納入其他月份需求筆數',r.different],['未排滿班次',...r.short],['未滿足偏好',...r.unmet],['注意','此為教學示範班表，請人工確認實際規則。']]),'排班說明');XLSX.writeFile(w,`班表初稿_${r.month}.xlsx`);notice('班表已匯出')};
